func HasResolvingUserWith(preds ...predicate.User) predicate.DiscussionThread {
	return predicate.DiscussionThread(func(s *sql.Selector) {
		step := newResolvingUserStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

