// And groups predicates with the AND operator between them.
func And(predicates ...predicate.DiscussionThread) predicate.DiscussionThread {
	return predicate.DiscussionThread(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.DiscussionThread) predicate.DiscussionThread {
	return predicate.DiscussionThread(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.DiscussionThread) predicate.DiscussionThread {
	return predicate.DiscussionThread(sql.NotPredicates(p))
}
